import java.util.*;
class Main {
  public static void main(String[] args) {
    Map<String, List<String>> m = new HashMap<>();
    m.computeIfAbsent("a", k -> new ArrayList<>()).add("x");
    m.computeIfAbsent("a", k -> new ArrayList<>()).add("y");
    System.out.println(m.get("a").size());
  }
}

