import java.util.*;
class Main {
  public static void main(String[] args) {
    Map<String, Integer> m = new HashMap<>();
    m.put("a", 1);
    m.compute("a", (k, v) -> v == null ? 1 : v + 10);
    m.compute("b", (k, v) -> v == null ? 1 : v + 10);
    System.out.println(m.get("a") + " " + m.get("b"));
  }
}

